import React from "react";

export const ContactForm = ({
  name,
  setName,
  phone,
  setPhone,
  email,
  setEmail,
  handleSubmit
}) => {
  return (
    <>
      <form onSubmit={handleSubmit}>
        <input 
        type='text' 
        value={name} 
        onChange={(e) => setName(e.target.value)}
        placeholder='Name'
        required>
        </input>

        <input 
        type='tel' 
        value={phone} 
        onChange={(e) => setPhone(e.target.value)}
        placeholder='Phone Number'
        pattern="[03][0-9]{8,9}"
        required>
        </input>

        <input 
        type='email' 
        value={email} 
        onChange={(e) => setEmail(e.target.value)}
        placeholder='Email'
        required>
        </input>

        <button type='submit'>
          Submit
        </button>
      </form>
    </>
  );
};
